1	/**
2	 * The landing page's only entry point into the phone demo.
3	 *
4	 * Everything the page needs to know lives here, so wiring the demo in is a
5	 * one-line swap for the dead <iframe> rather than a second pass over
6	 * landing-page.tsx. This module is deliberately tiny and imports nothing from
7	 * the demo chunk — scenes, primitives and CSS all arrive behind the lazy
8	 * boundary below, which is what keeps a visitor who never scrolls to the story
9	 * from downloading them (§6 rules 1–3).
10	 *
11	 * Failure modes are covered by construction, because a blank phone is the bug
12	 * this whole plan exists to fix (§7.1):
13	 *   • chunk still loading → static shell
14	 *   • chunk failed to load → static shell
15	 *   • scene threw while rendering → static shell
16	 *   • no IntersectionObserver → load immediately
17	 *   • Save-Data → no prefetch, and finished frames when it does load
18	 */
19	import { Component, Suspense, lazy, useCallback, useEffect, useState, type CSSProperties, type ReactNode } from 'react';
20	import { SCREEN_H, SCREEN_W } from './tokens';
21	import type { LandingPhoneScene, LandingPhoneState } from './types';
22	import { useApproaching, useStillPreference, useStoryProgress } from './useStoryProgress';
23	
24	const PhoneStage = lazy(() => import('./LandingPhoneDemo'));
25	
26	/**
27	 * Inline-styled on purpose: the shell is the pre-chunk state, so it must not
28	 * depend on landing-phone.css. It is a few hundred bytes and carries the
29	 * phone's silhouette, not its content.
30	 *
31	 * `bare` drops the silhouette: inside the landing page's own phone chrome the
32	 * shell is a screen, and a rounded, shadowed slab there would read as a second
33	 * phone floating behind the glass for as long as the chunk takes to arrive.
34	 */
35	function StaticShell({ scale = 1, rotateY = 0, bare = false, label = 'taptpay app' }: { scale?: number; rotateY?: number; bare?: boolean; label?: string }) {
36	  return (
37	    <div
38	      role="img"
39	      aria-label={label}
40	      data-demo-scene="shell"
41	      style={{
42	        width: SCREEN_W * scale,
43	        height: SCREEN_H * scale,
44	        background: 'linear-gradient(158deg,#0a1656 0%,#040D6D 46%,#0b1a6e 100%)',
45	        ...(bare
46	          ? null
47	          : {
48	              borderRadius: 54 * scale,
49	              boxShadow: '0 40px 120px rgba(4,13,109,0.55), inset 0 0 0 2px rgba(185,203,232,0.35)',
50	              transform: `perspective(2200px) rotateY(${rotateY}deg)`,
51	            }),
52	      }}
53	    />
54	  );
55	}
56	
57	class PhoneBoundary extends Component<{ fallback: ReactNode; children: ReactNode }, { failed: boolean }> {
58	  state = { failed: false };
59	
60	  static getDerivedStateFromError() {
61	    return { failed: true };
62	  }
63	
64	  componentDidCatch(error: unknown) {
65	    // The landing page is marketing, not a workflow: degrade to the shell and
66	    // leave a breadcrumb rather than taking the section down.
67	    if (import.meta.env?.DEV) console.error('[landing-phone] scene failed', error);
68	  }
69	
70	  render() {
71	    return this.state.failed ? this.props.fallback : this.props.children;
72	  }
73	}
74	
75	export type LandingPhoneMountProps = {
76	  /**
77	   * cinematic — scroll drives scene and step across the eight story zones.
78	   * industries — the tab picks the scene; step is driven by the tab's own
79	   * progress or pinned to the finished frame.
80	   */
81	  variant: 'cinematic' | 'industries';
82	  /** Industries only: which scene the selected tab shows. */
83	  scene?: LandingPhoneScene;
84	  /** Industries only: pin to an explicit milestone (e.g. replay controls). */
85	  state?: LandingPhoneState;
86	  scale?: number;
87	  /** Degrees of Y rotation at progress 0 and 1; the phone turns between them. */
88	  spin?: [number, number];
89	  /**
90	   * Industries only: "try it live" — tap-through and replay (§3.3). This is
91	   * local milestone stepping, never live production behaviour.
92	   */
93	  interactive?: boolean;
94	  /** Milestone count for the selected scene; supplied by the caller so the
95	   *  main chunk never imports the registry to find out. */
96	  steps?: number;
97	  /** Render the screen only, for callers that draw their own phone body. */
98	  bare?: boolean;
99	  /**
100	   * Cinematic only: selector for the tall element whose scroll travel is the
101	   * story. Omit when the mount itself is what scrolls.
102	   */
103	  storySelector?: string;
104	  className?: string;
105	  style?: CSSProperties;
106	};
107	
108	export function LandingPhoneMount({
109	  variant, scene, state, scale = 1, spin = [-18, 18], interactive = false, steps,
110	  bare = false, storySelector, className, style,
111	}: LandingPhoneMountProps) {
112	  const [ref, near] = useApproaching<HTMLDivElement>('600px');
113	  const { reducedMotion, saveData } = useStillPreference();
114	  const progress = useStoryProgress(ref, near && variant === 'cinematic', storySelector);
115	
116	  // Tap-through state for the Industries phone. Selecting a different tab
117	  // restarts that workflow from its own first milestone.
118	  const [step, setStep] = useState(0);
119	  useEffect(() => setStep(0), [scene]);
120	  const advance = useCallback(() => {
121	    setStep((s) => (steps && steps > 0 ? (s + 1) % steps : s + 1));
122	  }, [steps]);
123	
124	  const still = reducedMotion || saveData;
125	  // Save-Data viewers get the shell until the story is actually in view, not
126	  // merely approaching, so the chunk is never speculatively fetched for them.
127	  const load = saveData ? near && progress > 0 : near;
128	  const rotateY = variant === 'cinematic' ? spin[0] + (spin[1] - spin[0]) * progress : 0;
129	
130	  const shell = <StaticShell scale={scale} rotateY={rotateY} bare={bare} />;
131	
132	  // An Industries tab that is not being tapped through rests on its finished
133	  // frame, so the tab shows a completed workflow rather than an empty first step.
134	  const restStep = steps && steps > 0 ? steps - 1 : 0;
135	  const industriesState: LandingPhoneState | undefined = scene
136	    ? { scene, step: interactive ? step : restStep }
137	    : undefined;
138	
139	  return (
140	    <div
141	      ref={ref}
142	      className={className}
143	      style={{
144	        width: SCREEN_W * scale,
145	        height: SCREEN_H * scale,
146	        position: 'relative',
147	        // The landing page scales this element to fit its phone chrome
148	        // (landingRuntime initPhones), which only lands correctly from the
149	        // top-left corner of the 390 × 844 screen.
150	        transformOrigin: 'top left',
151	        ...style,
152	      }}
153	    >
154	      {load ? (
155	        <PhoneBoundary fallback={shell}>
156	          <Suspense fallback={shell}>
157	            <PhoneStage
158	              progress={progress}
159	              state={state ?? industriesState}
160	              rotateY={rotateY}
161	              scale={scale}
162	              still={still}
163	              bare={bare}
164	            />
165	          </Suspense>
166	        </PhoneBoundary>
167	      ) : (
168	        shell
169	      )}
170	
171	      {/*
172	        Only the Industries phone is interactive, and it exposes exactly two
173	        controls rather than turning every drawn button into a phantom control
174	        (§7.5). Both are real buttons, so they are keyboard reachable.
175	      */}
176	      {interactive && variant === 'industries' && (
177	        <>
178	          <button
179	            type="button"
180	            onClick={advance}
181	            aria-label={`step through the ${scene ?? 'demo'} workflow`}
182	            style={{ position: 'absolute', inset: 0, background: 'transparent', border: 'none', cursor: 'pointer', padding: 0 }}
183	          />
184	          <button
185	            type="button"
186	            onClick={() => setStep(0)}
187	            style={{
188	              // Bare mounts sit inside a clipping phone screen, so the control
189	              // has to live above the bottom edge rather than under it.
190	              position: 'absolute', bottom: bare ? 16 : -14, left: '50%', transform: 'translateX(-50%)',
191	              padding: '8px 18px', borderRadius: 999, border: '1px solid rgba(94,157,255,0.5)',
192	              background: 'rgba(4,13,109,0.9)', color: '#5E9DFF', cursor: 'pointer',
193	              font: "600 12px/1 'Outfit', system-ui", letterSpacing: '0.06em',
194	            }}
195	          >
196	            replay
197	          </button>
198	        </>
199	      )}
200	    </div>
201	  );
202	}
203	
204	export default LandingPhoneMount;
205

