/**
 * Plays one scene on a loop, returning the milestone currently on screen.
 *
 * Restarting is keyed on the scene, not on `steps`: four of the eight scenes
 * have the same milestone count, so keying on the number would let a new scene
 * inherit the previous one's position instead of opening at its own step 0.
 *
 * The elapsed clock is a ref, so a frame that lands inside the same milestone
 * costs nothing — React only hears about genuine milestone changes, which is
 * the guarantee the scroll controller used to provide.
 */
function useAutoplayStep(scene: LandingPhoneScene, steps: number, playing: boolean): number {
  const [step, setStep] = useState(0);

  useEffect(() => {
    setStep(0);
    if (!playing || steps <= 1) return;

    let frame = 0;
    let last = 0;
    let elapsed = 0;
    let current = 0;

    const tick = (now: number) => {
      frame = requestAnimationFrame(tick);
      if (last === 0) {
        last = now;
        return;
      }
      // rAF is already paused in a background tab, but a long task on a busy
      // page still hands back a large delta. Clamping it keeps the demo from
      // skipping a whole workflow in a single frame.
      elapsed += Math.min(now - last, 250);
      last = now;

      const next = stepAtElapsed(steps, elapsed);
      if (next === current) return;
      current = next;
      setStep(next);
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [scene, steps, playing]);

  return step;
}

/**
 * Story state for the cinematic phone: scroll picks the scene, a clock plays it.
 *
 * Scroll deliberately no longer scrubs the milestones. The cinematic act's
 * caption and HUD are scroll-driven and paired 1:1 with these eight scenes, so
 * the scene has to stay bound to scroll or the phone would contradict the words
 * beside it — but *within* a beat the workflow performs itself on a loop, which
 * is what makes it read as a demo rather than as a scrubbable filmstrip.
 *
 * `still` viewers (reduced motion, Save-Data) get the finished frame and no
 * clock at all: an indefinitely looping animation is the exact thing that
 * preference exists to opt out of.
 */
export function useStoryScene(progress: number, still = false, playing = true): LandingPhoneState {
  const { scene } = sceneAtProgress(progress);
  const steps = stepsFor(scene);
  const auto = useAutoplayStep(scene, steps, playing && !still);
  const step = still ? Math.max(0, steps - 1) : auto;

  return useMemo(() => ({ scene, step }), [scene, step]);
}

