              background: 'rgba(4,13,109,0.9)', color: '#5E9DFF', cursor: 'pointer',
              font: "600 12px/1 'Outfit', system-ui", letterSpacing: '0.06em',
            }}
          >
            replay
          </button>
        </>
      )}
    </div>
  );
}

export default LandingPhoneMount;

