1	/**
2	 * Shared presentational primitives for the landing phone demo.
3	 *
4	 * These are the vocabulary every scene is built from — the plan's §3.1 list —
5	 * so that seven scenes cost roughly one screen's worth of bytes instead of
6	 * seven independent page trees.
7	 *
8	 * Rules for anything added here:
9	 *   • presentational only — no state, no effects, no timers, no data fetching;
10	 *   • no icon pack, no motion library: inline SVG paths and CSS transitions;
11	 *   • every value traceable to the production terminals (see tokens.ts).
12	 */
13	import type { CSSProperties, ReactNode } from 'react';
14	import { BLUE, BLUE_40, BLUE_55, FONT, GREEN, NAVY, NAVY_25, NAVY_35, NAVY_50, OFFW, WHITE, fmt } from './tokens';
15	
16	/* ── icons ─────────────────────────────────────────────────────────────────
17	   Hand-rolled so the phone chunk never pulls in an icon library. */
18	const svg = (d: ReactNode, size = 20, stroke = 2): JSX.Element => (
19	  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={stroke} strokeLinecap="round" strokeLinejoin="round" aria-hidden>
20	    {d}
21	  </svg>
22	);
23	
24	export const Ic = {
25	  Check: (p?: { size?: number }) => svg(<path d="M20 6L9 17l-5-5" />, p?.size ?? 20, 2.6),
26	  Close: (p?: { size?: number }) => svg(<path d="M18 6L6 18M6 6l12 12" />, p?.size ?? 20),
27	  Back: (p?: { size?: number }) => svg(<path d="M19 12H5m6-6l-6 6 6 6" />, p?.size ?? 20),
28	  Chevron: (p?: { size?: number }) => svg(<path d="M9 18l6-6-6-6" />, p?.size ?? 18),
29	  Plus: (p?: { size?: number }) => svg(<path d="M12 5v14M5 12h14" />, p?.size ?? 20),
30	  Doc: (p?: { size?: number }) => svg(<><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z" /><path d="M14 2v6h6" /></>, p?.size ?? 16),
31	  Send: (p?: { size?: number }) => svg(<path d="M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z" />, p?.size ?? 14, 2.2),
32	};
33	
34	/* ── screen shell ───────────────────────────────────────────────────────── */
35	
36	/**
37	 * The terminal's two-part screen: an off-white working half over a navy half.
38	 * `topHeight` matches the production `height: 50%` unless a scene overrides it.
39	 */
40	export function Screen({ children, background = NAVY, style }: { children: ReactNode; background?: string; style?: CSSProperties }) {
41	  return (
42	    <div className="lp-screen" style={{ background, color: NAVY, ...style }}>
43	      {children}
44	    </div>
45	  );
46	}
47	
48	export function TopHalf({ children, height = '50%', background = OFFW }: { children: ReactNode; height?: string; background?: string }) {
49	  return (
50	    <div style={{ background, color: NAVY, height, display: 'flex', flexDirection: 'column', flexShrink: 0 }}>
51	      {children}
52	    </div>
53	  );
54	}
55	
56	export function BottomHalf({ children, padding = '38px 28px 28px' }: { children: ReactNode; padding?: string }) {
57	  return (
58	    <div style={{ flex: 1, background: NAVY, padding, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
59	      {children}
60	    </div>
61	  );
62	}
63	
64	/** Cancel / commit header used by every compose screen. */
65	export function SubHead({ commitReady = false }: { commitReady?: boolean }) {
66	  return (
67	    <div className="lp-subhead">
68	      <div className="lp-subhead-btn"><Ic.Close size={18} /></div>
69	      <div className="lp-subhead-btn" style={{ borderColor: commitReady ? NAVY : 'rgba(4,13,109,0.25)', color: commitReady ? NAVY : NAVY_25 }}>
70	        <Ic.Check size={18} />
71	      </div>
72	    </div>
73	  );
74	}
75	
76	export function TopBar({ title, right }: { title: string; right?: ReactNode }) {
77	  return (
78	    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '52px 22px 0' }}>
79	      <div style={{ fontFamily: FONT, fontWeight: 700, fontSize: 20, color: WHITE, letterSpacing: '-0.2px' }}>{title}</div>
80	      {right}
81	    </div>
82	  );
83	}
84	
85	/* ── amount + keypad ────────────────────────────────────────────────────── */
86	
87	export function Amount({ cents, size = 82, color, muted = false, style }: { cents: number; size?: number; color?: string; muted?: boolean; style?: CSSProperties }) {
88	  return (
89	    <div className="lp-amount" style={{ fontSize: size, color: color ?? (muted || cents === 0 ? NAVY_25 : NAVY), ...style }}>
90	      {fmt(cents)}
91	    </div>
92	  );
93	}
94	
95	const KEYS = ['1', '2', '3', '4', '5', '6', '7', '8', '9'];
96	
97	/**
98	 * The 3×4 keypad. `hit` lights the key the script is currently pressing —
99	 * the demo shows the press, it does not simulate a real one.
100	 */
101	export function Keypad({ hit }: { hit?: string }) {
102	  return (
103	    <div style={{ flex: 1, display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 14, alignItems: 'center', justifyItems: 'center' }}>
104	      {KEYS.map((d) => (
105	        <div key={d} className={`lp-kp lp-t${hit === d ? ' hit' : ''}`}>{d}</div>
106	      ))}
107	      <div className="lp-kp" style={{ visibility: 'hidden' }} aria-hidden />
108	      <div className={`lp-kp lp-t${hit === '0' ? ' hit' : ''}`}>0</div>
109	      <div className="lp-kp outline"><Ic.Back size={22} /></div>
110	    </div>
111	  );
112	}
113	
114	/* ── rows and controls ──────────────────────────────────────────────────── */
115	
116	/** Tenant / client selector row. `selected` draws the production active state. */
117	export function PersonRow({ name, sub, amount, selected = false }: { name: string; sub?: string; amount?: number; selected?: boolean }) {
118	  return (
119	    <div
120	      className="lp-t"
121	      style={{
122	        display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%',
123	        padding: '14px 16px', borderRadius: 14, border: 'none', textAlign: 'left',
124	        background: selected ? 'rgba(88,171,255,0.18)' : 'rgba(244,244,244,0.06)',
125	        boxShadow: selected ? `inset 0 0 0 1.5px ${BLUE}` : 'none',
126	      }}
127	    >
128	      <div style={{ display: 'flex', flexDirection: 'column', gap: 2, minWidth: 0 }}>
129	        <div style={{ fontWeight: 600, fontSize: 15, color: WHITE }}>{name}</div>
130	        {sub && <div style={{ fontWeight: 400, fontSize: 12.5, color: BLUE_55 }}>{sub}</div>}
131	      </div>
132	      {amount !== undefined && (
133	        <div style={{ fontWeight: 700, fontSize: 14, color: BLUE, fontVariantNumeric: 'tabular-nums' }}>{amount ? fmt(amount) : '—'}</div>
134	      )}
135	    </div>
136	  );
137	}
138	
139	/** Label + value + affordance, as used for rent amount, due date, doc chip. */
140	export function FieldRow({ label, value, action = '›', tone = 'navy', icon }: { label: string; value: string; action?: string; tone?: 'navy' | 'blue'; icon?: ReactNode }) {
141	  const dim = tone === 'navy' ? 'rgba(88,171,255,0.55)' : NAVY_50;
142	  return (
143	    <div style={{ width: '100%', marginTop: 14 }}>
144	      <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
145	        <span style={{ fontWeight: 600, fontSize: 11, color: dim, letterSpacing: '0.12em', textTransform: 'uppercase' }}>{label}</span>
146	      </div>
147	      <div className="lp-t" style={{ marginTop: 6, display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, padding: '12px 14px', borderRadius: 14, background: 'rgba(244,244,244,0.06)' }}>
148	        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8, fontWeight: 700, fontSize: 24, color: value ? BLUE : BLUE_40, fontVariantNumeric: 'tabular-nums' }}>
149	          {icon}
150	          {value}
151	        </span>
152	        <span style={{ fontWeight: 600, fontSize: 12.5, color: BLUE }}>{action}</span>
153	      </div>
154	    </div>
155	  );
156	}
157	
158	/** Frequency / split / deposit selector. */
159	export function Segmented({ options, active }: { options: readonly string[]; active: string }) {
160	  return (
161	    <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 12 }}>
162	      {options.map((o) => (
163	        <div key={o} className={`lp-pill lp-t ${o === active ? 'solid' : 'outline'}`}>{o}</div>
164	      ))}
165	    </div>
166	  );
167	}
168	
169	export type Status = 'sent' | 'paid' | 'active' | 'awaiting' | 'pending';
170	
171	const STATUS_COLOR: Record<Status, string> = {
172	  sent: BLUE,
173	  paid: GREEN,
174	  active: GREEN,
175	  awaiting: '#FFB02E',
176	  pending: '#FFB02E',
177	};
178	
179	export function StatusRow({ label, status, amount }: { label: string; status: Status; amount?: number }) {
180	  const c = STATUS_COLOR[status];
181	  return (
182	    <div className="lp-stack-card lp-t" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 14px', marginTop: 8 }}>
183	      <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
184	        <div className="lp-stack-title">{label}</div>
185	        <div style={{ fontWeight: 600, fontSize: 11, color: c, letterSpacing: '0.08em', textTransform: 'uppercase' }}>{status}</div>
186	      </div>
187	      {amount !== undefined && <div style={{ fontWeight: 800, fontSize: 16, color: NAVY, fontVariantNumeric: 'tabular-nums' }}>{fmt(amount)}</div>}
188	    </div>
189	  );
190	}
191	
192	/** Full-width commit button — "send & automate", "send", "confirm". */
193	export function PrimaryAction({ label, tone = 'blue', pressed = false }: { label: string; tone?: 'blue' | 'green'; pressed?: boolean }) {
194	  const bg = tone === 'green' ? GREEN : BLUE;
195	  return (
196	    <div
197	      className="lp-t"
198	      style={{
199	        marginTop: 16, width: '100%', height: 56, borderRadius: 999, background: bg, color: NAVY,
200	        display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
201	        fontFamily: FONT, fontWeight: 700, fontSize: 17,
202	        transform: pressed ? 'scale(0.96)' : 'none',
203	        boxShadow: '0 8px 24px rgba(4,13,109,0.28)',
204	      }}
205	    >
206	      {label}
207	    </div>
208	  );
209	}
210	
211	/** The post-send confirmation the story beats have to land on. */
212	export function SuccessCard({ title, sub, tone = 'green' }: { title: string; sub?: string; tone?: 'green' | 'blue' }) {
213	  const c = tone === 'green' ? GREEN : BLUE;
214	  return (
215	    <div className="lp-t" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12, padding: '28px 22px', textAlign: 'center' }}>
216	      <div style={{ width: 64, height: 64, borderRadius: 999, background: c, color: NAVY, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
217	        <Ic.Check size={30} />
218	      </div>
