226	export function Progress({ paid, total }: { paid: number; total: number }) {
227	  const pct = total > 0 ? Math.round((paid / total) * 100) : 0;
228	  return (
229	    <div style={{ width: '100%', marginTop: 14 }}>
230	      <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT, fontWeight: 600, fontSize: 12.5, color: BLUE_55 }}>
231	        <span>{`${paid} of ${total} paid`}</span>
232	        <span>{`${pct}%`}</span>
233	      </div>
234	      <div style={{ marginTop: 8, height: 8, borderRadius: 999, background: 'rgba(88,171,255,0.18)', overflow: 'hidden' }}>
235	        <div className="lp-grow" style={{ width: `${pct}%`, height: '100%', borderRadius: 999, background: GREEN }} />
236	      </div>
237	    </div>
238	  );
239	}
