242	export function Wordmark({ merchant, sub }: { merchant: string; sub?: string }) {
243	  return (
244	    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4, paddingTop: 8 }}>
245	      <div style={{ fontFamily: "'Larken', Georgia, serif", fontWeight: 900, fontSize: 22, color: NAVY }}>{merchant}</div>
