/**
 * Shared contract for the landing-page phone demo.
 *
 * Everything in this module is pure data — no React runtime, no DOM, no Date.
 * The scroll controller, the scene modules and the tests all compile against
 * these types, which is what lets the three vertical lanes be built and
 * verified independently of each other.
 */
import type { ComponentType } from 'react';

/** One scene per landing story zone: intro + cards 01–07. */
export type LandingPhoneScene =
  | 'overview'
  | 'rent-weekly'
  | 'property-bill'
  | 'trades-invoice'
  | 'quote-deposit'
  | 'retail-sale'
  | 'retail-split'
  | 'checkout-wallet';

/** The complete demo state. `step` is always a valid milestone for `scene`. */
export type LandingPhoneState = {
  scene: LandingPhoneScene;
  step: number;
};

/**
 * Scenes render from `step` alone. They hold no state of their own, so any
 * scroll position — forward, backward, or jumped — produces the same frame.
 */
export type SceneProps = {
  step: number;
  /** true when the viewer asked for reduced motion or Save-Data. */
  still?: boolean;
};

export type SceneDefinition = {
  id: LandingPhoneScene;
  /** Milestone count. `step` runs 0 … steps - 1. */
  steps: number;
  /** Announced politely when the scene reaches its final milestone. */
  label: string;
  Component: ComponentType<SceneProps>;
};

/** Registry shape. Every scene id must be present — the type enforces it. */
export type SceneRegistry = Record<LandingPhoneScene, SceneDefinition>;

content.content:
  width: 70px;
  height: 70px;
  border-radius: 999px;
  background: #58abff;
  color: #040d6d;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 6px 18px rgba(4, 13, 109, 0.25);
  border: none;
}

/* ── step-driven motion ─────────────────────────────────────────────────────
   Scenes never schedule anything. They render a frame for the current step and
   these transitions carry the eye between frames, so a scene change can never
   leave an animation running behind it. */
.lp-t {
  transition: opacity 0.32s ease, transform 0.32s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.lp-in {
  opacity: 1;
  transform: none;
}
.lp-out-up {
  opacity: 0;
  transform: translateY(-10px);
}
.lp-out-down {
  opacity: 0;
  transform: translateY(14px);
}
.lp-grow {
  transition: width 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ── phone body (CSS 3D, replaces the WebGL slab) ──────────────────────────── */
.lp-phone {
  position: relative;
  transform-style: preserve-3d;
  will-change: transform;
}
.lp-face {
  position: absolute;
  inset: 0;
  backface-visibility: hidden;
  border-radius: 54px;
  overflow: hidden;
}
.lp-face-back {
  transform: rotateY(180deg);
  background-size: cover;
  background-position: center;
}
.lp-rim {
  position: absolute;
  inset: -2px;
  border-radius: 56px;
  background: linear-gradient(145deg, #b9cbe8 0%, #6f86ad 42%, #dce6f7 68%, #56688c 100%);
  transform: translateZ(-6px);
}
.lp-glare {
  position: absolute;
  inset: 0;
  border-radius: 54px;
  pointer-events: none;
  background: linear-gradient(118deg, rgba(255, 255, 255, 0) 38%, rgba(255, 255, 255, 0.22) 50%, rgba(255, 255, 255, 0) 62%);
}
.lp-island {
  position: absolute;
  top: 11px;
  left: 50%;
  transform: translateX(-50%);
  width: 118px;
  height: 33px;
  border-radius: 999px;
  background: #05060f;
  z-index: 40;
}

/* Enhanced 3D is additive: if transforms are unsupported the screen still
   renders, flat, rather than showing a blank phone. */
@supports not (transform-style: preserve-3d) {
  .lp-phone {
    transform: none !important;
  }
  .lp-face-back,
  .lp-rim {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .lp-t,
  .lp-grow {
    transition: none;
  }
}
=== registry ===
/**
 * The one scene registry, used by both the cinematic phone and the Industries
 * phone so the two can never drift apart.
 *
 * Scenes are imported statically on purpose: the whole demo is one lazily
 * loaded chunk (§6 rule 3), so changing scene must not cost a network request.
 *
 * Adding a scene means adding a member to LandingPhoneScene in types.ts — the
 * SceneRegistry type then fails to compile until it is registered here.
 */
import type { LandingPhoneScene, SceneRegistry } from '../types';
import { overviewScene } from './overview';
import { rentWeeklyScene } from './rent-weekly';
import { propertyBillScene } from './property-bill';
import { tradesInvoiceScene } from './trades-invoice';
import { quoteDepositScene } from './quote-deposit';
import { retailSaleScene } from './retail-sale';
import { retailSplitScene } from './retail-split';
import { checkoutWalletScene } from './checkout-wallet';

export const SCENES: SceneRegistry = {
  overview: overviewScene,
  'rent-weekly': rentWeeklyScene,
  'property-bill': propertyBillScene,
  'trades-invoice': tradesInvoiceScene,
  'quote-deposit': quoteDepositScene,
  'retail-sale': retailSaleScene,
  'retail-split': retailSplitScene,
  'checkout-wallet': checkoutWalletScene,
};

export const stepsFor = (scene: LandingPhoneScene): number => SCENES[scene].steps;

/** Default scene per Industries tab (§3.3). */
export const INDUSTRY_SCENE = {
  property: 'rent-weekly',
  trades: 'quote-deposit',
  retail: 'retail-sale',
} as const satisfies Record<string, LandingPhoneScene>;

