/** Milliseconds a mid-workflow milestone is held before the next one. */
export const STEP_MS = 900;
/**
 * The finished frame is held longer than the rest. Without it the loop snaps
 * from the completed workflow straight back to an empty first step, which reads
 * as a glitch rather than as a replay.
 */
export const HOLD_MS = 1900;

/** One full play-through of a scene, in milliseconds. */
export function cycleLength(steps: number, stepMs = STEP_MS, holdMs = HOLD_MS): number {
  return steps <= 1 ? holdMs : (steps - 1) * stepMs + holdMs;
}

/**
 * Milestone of an *autoplaying* scene, `elapsed` ms after it began.
 *
 * The scene plays 0 → last at `stepMs` each, rests on the finished frame for
 * `holdMs`, then repeats — a video on loop (§3.2, revised). Kept pure and
 * separate from the rAF loop that feeds it so the looping contract is unit
 * tested rather than eyeballed in a browser, exactly like the scroll mapping
 * above it.
 */
export function stepAtElapsed(
  steps: number,
  elapsed: number,
  stepMs = STEP_MS,
  holdMs = HOLD_MS,
): number {
  if (steps <= 1) return 0;
  const ms = Number.isFinite(elapsed) && elapsed > 0 ? elapsed : 0;
  const last = steps - 1;
  const playing = last * stepMs;
  const t = ms % cycleLength(steps, stepMs, holdMs);
  return t >= playing ? last : Math.floor(t / stepMs);
}

input.new_string:
/* ── autoplay timing ───────────────────────────────────────────────────────
   A uniform beat is what makes a demo read as a robot stepping through slides.
   Real use has a rhythm: the press itself is over in a moment, the screen it
   opens has to be readable, and the finished result wants a breath before the
   session starts again. Scenes declare a duration per step from this vocabulary. */

/** A press: long enough to see the key light and the control sink, no longer. */
export const TAP_MS = 200;
/** A screen the eye has to actually read before the next move. */
export const BEAT_MS = 780;
/** A moment on something worth looking at — an amount landing, a QR appearing. */
export const DWELL_MS = 1150;
/**
 * The finished frame, held before the session replays. Without it the loop snaps
 * from a completed workflow straight back to an empty first screen, which reads
 * as a glitch rather than as the same person starting over.
 */
export const HOLD_MS = 2100;

/** Fallback for a scene that declares no rhythm of its own. */
export function uniformBeats(steps: number, ms = BEAT_MS): number[] {
  if (steps <= 1) return [HOLD_MS];
  return Array.from({ length: steps }, (_, i) => (i === steps - 1 ? HOLD_MS : ms));
}

/** One full play-through, in milliseconds. */
export function cycleLength(beats: readonly number[]): number {
  let total = 0;
  for (const b of beats) total += b > 0 && Number.isFinite(b) ? b : 0;
  return total > 0 ? total : HOLD_MS;
}

/**
 * Step of an *autoplaying* scene, `elapsed` ms after it began.
 *
 * `beats[i]` is how long step `i` stays on screen. The scene plays 0 → last and
 * then repeats, so the phone performs the workflow rather than waiting to be
 * scrubbed through it. Kept pure and separate from the rAF loop that feeds it,
 * so the looping contract is unit tested rather than eyeballed in a browser —
 * exactly like the scroll mapping above it.
 */
export function stepAtElapsed(beats: readonly number[], elapsed: number): number {
  if (beats.length <= 1) return 0;
  const ms = Number.isFinite(elapsed) && elapsed > 0 ? elapsed : 0;
  let t = ms % cycleLength(beats);
  for (let i = 0; i < beats.length; i++) {
    const b = beats[i] > 0 && Number.isFinite(beats[i]) ? beats[i] : 0;
    if (t < b) return i;
    t -= b;
  }
  return beats.length - 1;
}

