/**
 * Scene/step resolution for the landing phone demo.
 *
 * Two inputs, deliberately split:
 *
 *   scroll  → *which* scene (`sceneAtProgress`), so the phone always shows the
 *             feature the cinematic caption is describing;
 *   a clock → *how far through* it (`stepAtElapsed`), so the workflow performs
 *             itself on a loop instead of being scrubbed by the reader.
 *
 * Both halves are pure arithmetic, which is what makes the plan's requirements
 * (§3.2) provable in a unit test rather than eyeballed in a browser:
 *
 *   ordering  — every milestone is visited, in order
 *   looping   — the finished frame is held, then the workflow replays
 *   jump      — any progress maps to exactly one scene, with no replay
 *   re-entry  — a zone always starts at its own step 0
 *
 * `stepAtProgress` and `resolveState` are the older scroll-scrubbed mapping.
 * They no longer drive the cinematic phone, but they remain the definition of a
 * milestone boundary and are what the Industries tabs' pinning is derived from.
 *
 * The rAF loop that measures elapsed time lives in the component; nothing here
 * holds a timer, so no in-flight animation can survive a scene change and leak
 * into the next one. Scenes render from `step`; they must not schedule their
 * own transitions.
 */
import type { LandingPhoneScene, LandingPhoneState } from './types';

/** Story order: intro + cards 01–07, eight equal zones (§3.2). */
export const SCENE_ORDER: readonly LandingPhoneScene[] = [
  'overview',
  'rent-weekly',
  'property-bill',
  'trades-invoice',
  'quote-deposit',
  'retail-sale',
  'retail-split',
  'checkout-wallet',
];

export const ZONE_COUNT = SCENE_ORDER.length;

const clamp01 = (n: number) => (n < 0 ? 0 : n > 1 ? 1 : n);

/** Maps overall story progress (0–1) to a zone and the progress within it. */
export function sceneAtProgress(progress: number): {
  scene: LandingPhoneScene;
  local: number;
} {
  const p = clamp01(Number.isFinite(progress) ? progress : 0);
  const scaled = p * ZONE_COUNT;
  const index = Math.min(Math.floor(scaled), ZONE_COUNT - 1);
  return { scene: SCENE_ORDER[index], local: clamp01(scaled - index) };
}

/**
 * Splits a zone into `steps` equal milestones. The final milestone owns the
 * end of the zone, so scrolling a scene fully through always finishes it.
 */
export function stepAtProgress(steps: number, local: number): number {
  if (steps <= 1) return 0;
  const slice = Math.floor(clamp01(local) * steps);
  return Math.min(slice, steps - 1);
}

/** Milliseconds a mid-workflow milestone is held before the next one. */
export const STEP_MS = 900;
/**
 * The finished frame is held longer than the rest. Without it the loop snaps
 * from the completed workflow straight back to an empty first step, which reads
 * as a glitch rather than as a replay.
 */
export const HOLD_MS = 1900;

/** One full play-through of a scene, in milliseconds. */
export function cycleLength(steps: number, stepMs = STEP_MS, holdMs = HOLD_MS): number {
  return steps <= 1 ? holdMs : (steps - 1) * stepMs + holdMs;
}

/**
 * Milestone of an *autoplaying* scene, `elapsed` ms after it began.
 *
 * The scene plays 0 → last at `stepMs` each, rests on the finished frame for
 * `holdMs`, then repeats — a video on loop (§3.2, revised). Kept pure and
 * separate from the rAF loop that feeds it so the looping contract is unit
 * tested rather than eyeballed in a browser, exactly like the scroll mapping
 * above it.
 */
export function stepAtElapsed(
  steps: number,
  elapsed: number,
  stepMs = STEP_MS,
  holdMs = HOLD_MS,
): number {
  if (steps <= 1) return 0;
  const ms = Number.isFinite(elapsed) && elapsed > 0 ? elapsed : 0;
  const last = steps - 1;
  const playing = last * stepMs;
  const t = ms % cycleLength(steps, stepMs, holdMs);
  return t >= playing ? last : Math.floor(t / stepMs);
}

export type StepsFor = (scene: LandingPhoneScene) => number;

/** The single source of truth: progress in, complete state out. */
export function resolveState(progress: number, stepsFor: StepsFor): LandingPhoneState {
  const { scene, local } = sceneAtProgress(progress);
  return { scene, step: stepAtProgress(stepsFor(scene), local) };
}

/** Reduced-motion and Save-Data viewers get the finished frame, not the build-up. */
export function finalState(scene: LandingPhoneScene, stepsFor: StepsFor): LandingPhoneState {
  return { scene, step: Math.max(0, stepsFor(scene) - 1) };
}

export const sameState = (a: LandingPhoneState, b: LandingPhoneState) =>
  a.scene === b.scene && a.step === b.step;

/**
 * Wraps `resolveState` so React only re-renders on an actual milestone change.
 * Scroll fires far more often than the demo changes; without this the phone
 * would set state on every frame.
 */
export function createSceneController(stepsFor: StepsFor, initial?: LandingPhoneState) {
  let current: LandingPhoneState = initial ?? { scene: SCENE_ORDER[0], step: 0 };
  return {
    get state(): LandingPhoneState {
      return current;
    },
    /** Returns the new state only when it changed, else null. */
    update(progress: number): LandingPhoneState | null {
      const next = resolveState(progress, stepsFor);
      if (sameState(next, current)) return null;
      current = next;
      return next;
    },
    /** Direct selection, used by the Industries tabs and replay control. */
    set(next: LandingPhoneState): LandingPhoneState | null {
      if (sameState(next, current)) return null;
      current = next;
      return next;
    },
  };
}

