/* ── the session ──────────────────────────────────────────────────────────
   One pass through the retail terminal, written as the frames a viewer sees
   rather than as milestones. It opens where the merchant actually opens the
   app — the terminal home — and every screen change is preceded by a visible
   press on the control that causes it, so the phone reads as somebody using it
   rather than as a slideshow advancing itself.

   `ms` is how long the frame holds. Presses are brief; the screens they open
   linger. */
type Frame = {
  ms: number;
  /** What is on screen. */
  render: (seq: number) => ReactNode;
};

const KEY_SEQUENCE = ['1', '2', '5', '0'] as const;
/** The amount as each key lands: $0.00 → $1.25 → $12.50. */
const KEY_AMOUNTS = [1, 12, 125, 1250];

const FRAMES: Frame[] = [
  // Terminal home, nothing pending — where the merchant starts.
  { ms: BEAT_MS, render: () => <Terminal total={0} line="no items yet" items={[]} /> },
  // Tap + to start a sale.
  { ms: TAP_MS, render: (seq) => <Terminal total={0} line="no items yet" items={[]} tapFab seq={seq} /> },
  // Keypad opens empty.
  { ms: 420, render: () => <KeypadScreen cents={0} /> },
  // Type 1, 2, 5, 0 — each press visible, the amount building as it goes.
  ...KEY_SEQUENCE.map((key, i) => ({
    ms: TAP_MS,
    render: (seq: number) => <KeypadScreen cents={KEY_AMOUNTS[i]} hit={key} seq={seq} commitReady={i > 0} />,
  })),
  // The finished amount, read for a moment before committing.
  { ms: DWELL_MS, render: () => <KeypadScreen cents={RETAIL.saleCents} commitReady /> },
  // Tap ✓ to name the item.
  { ms: TAP_MS, render: (seq) => <KeypadScreen cents={RETAIL.saleCents} commitReady tapCommit seq={seq} /> },
  { ms: DWELL_MS, render: () => <DetailsScreen /> },
  // Tap confirm.
  { ms: TAP_MS, render: (seq) => <DetailsScreen tapConfirm seq={seq} /> },
  { ms: BEAT_MS, render: () => <Terminal total={RETAIL.saleCents} line={RETAIL.saleItem} sub="tap send to share payment" items={[]} cancel send /> },
  // Tap send to raise the QR.
  { ms: TAP_MS, render: (seq) => <Terminal total={RETAIL.saleCents} line={RETAIL.saleItem} sub="tap send to share payment" items={[]} cancel send tapSend seq={seq} /> },
  { ms: DWELL_MS + 400, render: () => <ShareScreen /> },
  // Back on the terminal, the sale sitting in the stack.
  { ms: DWELL_MS, render: () => <Terminal total={0} line="no items yet" items={[{ name: RETAIL.saleItem, amount: RETAIL.saleCents, status: 'awaiting payment' }]} /> },
  // The customer pays: banner drops in, row flips to paid.
  { ms: HOLD_MS, render: () => <Terminal total={0} line="no items yet" items={[{ name: RETAIL.saleItem, amount: RETAIL.saleCents, status: 'paid' }]} banner={RETAIL.saleCents} /> },
];

function RetailSale({ step }: SceneProps) {
  const i = Math.min(Math.max(step, 0), FRAMES.length - 1);
  return <>{FRAMES[i].render(i)}</>;
}

export const retailSaleScene: SceneDefinition = {
  id: 'retail-sale',
  steps: FRAMES.length,
  beats: FRAMES.map((f) => f.ms),
  label: '$12.50 flat white sale paid',
  Component: RetailSale,
};

