  }, [state.scene, state.step]);
  return message;
}

const SR_ONLY = {
  position: 'absolute', width: 1, height: 1, overflow: 'hidden',
  clip: 'rect(0 0 0 0)', whiteSpace: 'nowrap',
} as const;

export function LandingPhoneDemo({ state, rotateY = 0, rotateX = 0, scale = 1, still = false, bare = false, className }: LandingPhoneDemoProps) {
  const def = SCENES[state.scene];
  const Scene = def.Component;
  const announcement = useSceneAnnouncement(state);

  // The scene always renders at its canonical 390 × 844 and is scaled as a
  // whole, so no scene has to know what size it is being shown at.
  const screen = (
    <div
      style={{
        width: SCREEN_W,
        height: SCREEN_H,
        transform: scale === 1 ? undefined : `scale(${scale})`,
        transformOrigin: 'top left',
        position: 'relative',
        overflow: 'hidden',
        background: '#fff',
      }}
    >
      <Scene step={state.step} still={still} />
      {!bare && <div className="lp-island" aria-hidden />}
    </div>
  );

  const live = (
    <p aria-live="polite" style={SR_ONLY}>
      {announcement}
    </p>
  );

  if (bare) {
    // No .lp-phone here: preserve-3d and a perspective transform belong to
    // whoever owns the phone body, and this element is only its screen.
    return (
      <div
        className={className}
        data-demo-scene={state.scene}
        data-demo-step={state.step}
        role="img"
        aria-label={def.label}
        style={{ width: SCREEN_W * scale, height: SCREEN_H * scale, position: 'relative', overflow: 'hidden', background: '#fff' }}
      >
        {screen}
        {live}
      </div>
    );
  }

  return (
    <div
      className={`lp-phone${className ? ` ${className}` : ''}`}
      data-demo-scene={state.scene}
      data-demo-step={state.step}
      style={{
        width: SCREEN_W * scale,
        height: SCREEN_H * scale,
        transform: `perspective(2200px) rotateX(${rotateX}deg) rotateY(${rotateY}deg)`,
      }}
    >
      <div className="lp-rim" aria-hidden />
      <div className="lp-face lp-face-back" aria-hidden style={{ backgroundImage: "url('/assets/shell-back.webp')" }} />
      <div className="lp-face" role="img" aria-label={def.label}>
        {screen}
        <div className="lp-glare" aria-hidden />
      </div>
      {live}
    </div>
  );
}

/**
 * Plays one scene on a loop, returning the milestone currently on screen.
 *
 * Restarting is keyed on the scene, not on `steps`: four of the eight scenes
 * have the same milestone count, so keying on the number would let a new scene
 * inherit the previous one's position instead of opening at its own step 0.
 *
 * The elapsed clock is a ref, so a frame that lands inside the same milestone
 * costs nothing — React only hears about genuine milestone changes, which is
 * the guarantee the scroll controller used to provide.
 */
function useAutoplayStep(scene: LandingPhoneScene, beats: readonly number[], playing: boolean): number {
  const [step, setStep] = useState(0);

  useEffect(() => {
    setStep(0);
    if (!playing || beats.length <= 1) return;

    let frame = 0;
    let last = 0;
    let elapsed = 0;
    let current = 0;

    const tick = (now: number) => {
      frame = requestAnimationFrame(tick);
      if (last === 0) {
        last = now;
        return;
      }
      // rAF is already paused in a background tab, but a long task on a busy
      // page still hands back a large delta. Clamping it keeps the demo from
      // skipping a whole workflow in a single frame.
      elapsed += Math.min(now - last, 250);
      last = now;

      const next = stepAtElapsed(beats, elapsed);
      if (next === current) return;
      current = next;
      setStep(next);
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
    // `beats` is a stable array owned by the scene definition, so identity is a
    // sound dependency here and changes exactly when the scene does.
  }, [scene, beats, playing]);

  return step;
}

/**
 * Story state for the cinematic phone: scroll picks the scene, a clock plays it.
 *
 * Scroll deliberately no longer scrubs the milestones. The cinematic act's
 * caption and HUD are scroll-driven and paired 1:1 with these eight scenes, so
 * the scene has to stay bound to scroll or the phone would contradict the words
 * beside it — but *within* a beat the workflow performs itself on a loop, which
 * is what makes it read as a demo rather than as a scrubbable filmstrip.
 *
 * `still` viewers (reduced motion, Save-Data) get the finished frame and no
 * clock at all: an indefinitely looping animation is the exact thing that
 * preference exists to opt out of.
 */
export function useStoryScene(progress: number, still = false, playing = true): LandingPhoneState {
  const { scene } = sceneAtProgress(progress);
  const steps = stepsFor(scene);
  const auto = useAutoplayStep(scene, steps, playing && !still);
  const step = still ? Math.max(0, steps - 1) : auto;

  return useMemo(() => ({ scene, step }), [scene, step]);
}

/**
 * Mode-aware entry point for the lazily loaded chunk.
 *
 * The cinematic phone passes `progress` and lets the controller pick the
 * scene; the Industries phone passes an explicit `state` for the selected tab.
 * Both render the same scenes from the same registry, so the two phones cannot
 * drift apart (§3.3).
 *
 * This is the chunk's default export: LandingPhoneMount lazy-imports this
 * module, so everything below — scenes, primitives, CSS — lands in one chunk
 * that is fetched once and never re-fetched when the scene changes.
 */
export type PhoneStageProps = Omit<LandingPhoneDemoProps, 'state'> & {
  progress?: number;
  state?: LandingPhoneState;
  /** False parks the autoplay clock — the phone is off screen (§6 rule 9). */
  playing?: boolean;
};

export function PhoneStage({ progress = 0, state, still = false, playing = true, ...rest }: PhoneStageProps) {
  // An explicit `state` means the Industries phone, which owns its own
  // milestone; running a clock there would burn a rAF loop on a discarded value.
  const story = useStoryScene(progress, still, playing && !state);
  return <LandingPhoneDemo {...rest} still={still} state={state ?? story} />;
}

export default PhoneStage;

