 * The cinematic phone no longer scrubs its milestones with scroll: scroll picks
 * the scene, and the scene then plays itself on a loop. These are that loop's
 * promises — the ones a reader would notice breaking.
 */
describe('autoplay', () => {
  it('opens every scene on its own first milestone', () => {
    for (const id of SCENE_ORDER) {
      expect(stepAtElapsed(SCENES[id].steps, 0)).toBe(0);
    }
  });

  it('advances one milestone at a time, in order, with none skipped', () => {
    for (const id of SCENE_ORDER) {
      const steps = SCENES[id].steps;
      const seen: number[] = [];
      // Sample far finer than the milestone width, so a skipped milestone
      // cannot hide between two samples.
      for (let ms = 0; ms <= cycleLength(steps); ms += 10) {
        const s = stepAtElapsed(steps, ms);
        if (seen.length === 0 || seen[seen.length - 1] !== s) seen.push(s);
      }
      // 0 … last, then the wrap back to 0 at the end of the cycle.
      expect(seen).toEqual([...Array.from({ length: steps }, (_, i) => i), 0]);
    }
  });

  it('holds the finished frame longer than a mid-workflow milestone', () => {
    const steps = 6;
    const last = steps - 1;
    const heldFor = (step: number) => {
      let ms = 0;
      let count = 0;
      while (ms < cycleLength(steps)) {
        if (stepAtElapsed(steps, ms) === step) count++;
        ms += 1;
      }
      return count;
    };
    expect(heldFor(last)).toBe(HOLD_MS);
    expect(heldFor(0)).toBe(STEP_MS);
    expect(heldFor(last)).toBeGreaterThan(heldFor(0));
  });

  it('repeats forever rather than resting on the finished frame', () => {
    const steps = 8;
    const cycle = cycleLength(steps);
    for (let n = 1; n <= 40; n++) {
      // Every cycle is identical to the first, so the loop cannot drift.
      expect(stepAtElapsed(steps, n * cycle)).toBe(0);
      expect(stepAtElapsed(steps, n * cycle + STEP_MS * 2 + 5)).toBe(2);
    }
  });

  it('never returns a milestone outside its scene', () => {
    for (const id of SCENE_ORDER) {
      const steps = SCENES[id].steps;
      for (let ms = 0; ms < cycleLength(steps) * 3; ms += 7) {
        const s = stepAtElapsed(steps, ms);
        expect(s).toBeGreaterThanOrEqual(0);
        expect(s).toBeLessThan(steps);
      }
    }
  });

  it('clamps a hostile clock instead of throwing', () => {
    expect(stepAtElapsed(6, -1000)).toBe(0);
    expect(stepAtElapsed(6, Number.NaN)).toBe(0);
    expect(stepAtElapsed(6, Number.POSITIVE_INFINITY)).toBe(0);
    expect(stepAtElapsed(1, 99_999)).toBe(0);
    expect(stepAtElapsed(0, 99_999)).toBe(0);
  });
});

