/** The rhythm each scene actually plays at. */
const beatsOf = (id: LandingPhoneScene) => SCENES[id].beats ?? uniformBeats(SCENES[id].steps);

describe('autoplay', () => {
  it('gives every scene one beat per step', () => {
    for (const id of SCENE_ORDER) {
      expect(beatsOf(id)).toHaveLength(SCENES[id].steps);
    }
  });

  it('gives every beat a positive, finite duration', () => {
    for (const id of SCENE_ORDER) {
      for (const b of beatsOf(id)) {
        expect(Number.isFinite(b)).toBe(true);
        expect(b).toBeGreaterThan(0);
      }
    }
  });

  it('opens every scene on its own first step', () => {
    for (const id of SCENE_ORDER) {
      expect(stepAtElapsed(beatsOf(id), 0)).toBe(0);
    }
  });

  it('advances one step at a time, in order, with none skipped', () => {
    for (const id of SCENE_ORDER) {
      const beats = beatsOf(id);
      const seen: number[] = [];
      // Sample far finer than the shortest beat, so a skipped step cannot hide
      // between two samples.
      for (let ms = 0; ms <= cycleLength(beats); ms += 5) {
        const s = stepAtElapsed(beats, ms);
        if (seen.length === 0 || seen[seen.length - 1] !== s) seen.push(s);
      }
      // 0 … last, then the wrap back to 0 at the end of the cycle.
      expect(seen).toEqual([...beats.map((_, i) => i), 0]);
    }
  });

  it('holds each step for exactly the beat it declares', () => {
    const beats = [TAP_MS, BEAT_MS, DWELL_MS, HOLD_MS];
    const heldFor = (step: number) => {
      let count = 0;
      for (let ms = 0; ms < cycleLength(beats); ms++) {
        if (stepAtElapsed(beats, ms) === step) count++;
      }
      return count;
    };
    beats.forEach((b, i) => expect(heldFor(i)).toBe(b));
    // The point of declaring a rhythm: a press is brief, a result lingers.
    expect(heldFor(0)).toBeLessThan(heldFor(3));
  });

  it('keeps presses shorter than the screens they open', () => {
    // A press the eye cannot catch is the failure this guards: every scene must
    // hold its longest frame well past its shortest.
    for (const id of SCENE_ORDER) {
      const beats = beatsOf(id);
      expect(Math.max(...beats)).toBeGreaterThanOrEqual(Math.min(...beats) * 2);
    }
  });

  it('repeats forever rather than resting on the finished frame', () => {
    const beats = beatsOf('retail-sale');
    const cycle = cycleLength(beats);
    for (let n = 1; n <= 40; n++) {
      // Every cycle is identical to the first, so the loop cannot drift.
      expect(stepAtElapsed(beats, n * cycle)).toBe(0);
      expect(stepAtElapsed(beats, n * cycle + beats[0] + 5)).toBe(1);
    }
  });

  it('never returns a step outside its scene', () => {
    for (const id of SCENE_ORDER) {
      const beats = beatsOf(id);
      for (let ms = 0; ms < cycleLength(beats) * 3; ms += 7) {
        const s = stepAtElapsed(beats, ms);
        expect(s).toBeGreaterThanOrEqual(0);
        expect(s).toBeLessThan(SCENES[id].steps);
      }
    }
  });

  it('clamps a hostile clock instead of throwing', () => {
    const beats = [200, 800, 200, 2000];
    expect(stepAtElapsed(beats, -1000)).toBe(0);
    expect(stepAtElapsed(beats, Number.NaN)).toBe(0);
    expect(stepAtElapsed(beats, Number.POSITIVE_INFINITY)).toBe(0);
    expect(stepAtElapsed([500], 99_999)).toBe(0);
    expect(stepAtElapsed([], 99_999)).toBe(0);
    // A bad beat must not swallow the steps after it.
    expect(stepAtElapsed([0, 500], 100)).toBe(1);
    expect(cycleLength([])).toBeGreaterThan(0);
  });
});

