1	/**
2	 * Scene/step resolution for the landing phone demo.
3	 *
4	 * Two inputs, deliberately split:
5	 *
6	 *   scroll  → *which* scene (`sceneAtProgress`), so the phone always shows the
7	 *             feature the cinematic caption is describing;
8	 *   a clock → *how far through* it (`stepAtElapsed`), so the workflow performs
9	 *             itself on a loop instead of being scrubbed by the reader.
10	 *
11	 * Both halves are pure arithmetic, which is what makes the plan's requirements
12	 * (§3.2) provable in a unit test rather than eyeballed in a browser:
13	 *
14	 *   ordering  — every milestone is visited, in order
15	 *   looping   — the finished frame is held, then the workflow replays
16	 *   jump      — any progress maps to exactly one scene, with no replay
17	 *   re-entry  — a zone always starts at its own step 0
18	 *
19	 * `stepAtProgress` and `resolveState` are the older scroll-scrubbed mapping.
20	 * They no longer drive the cinematic phone, but they remain the definition of a
21	 * milestone boundary and are what the Industries tabs' pinning is derived from.
22	 *
23	 * The rAF loop that measures elapsed time lives in the component; nothing here
24	 * holds a timer, so no in-flight animation can survive a scene change and leak
25	 * into the next one. Scenes render from `step`; they must not schedule their
26	 * own transitions.
27	 */
28	import type { LandingPhoneScene, LandingPhoneState } from './types';
29	
30	/** Story order: intro + cards 01–07, eight equal zones (§3.2). */
31	export const SCENE_ORDER: readonly LandingPhoneScene[] = [
32	  'overview',
33	  'rent-weekly',
34	  'property-bill',
35	  'trades-invoice',
36	  'quote-deposit',
37	  'retail-sale',
38	  'retail-split',
39	  'checkout-wallet',
40	];
41	
42	export const ZONE_COUNT = SCENE_ORDER.length;
43	
44	const clamp01 = (n: number) => (n < 0 ? 0 : n > 1 ? 1 : n);
45	
46	/** Maps overall story progress (0–1) to a zone and the progress within it. */
47	export function sceneAtProgress(progress: number): {
48	  scene: LandingPhoneScene;
49	  local: number;
50	} {
51	  const p = clamp01(Number.isFinite(progress) ? progress : 0);
52	  const scaled = p * ZONE_COUNT;
53	  const index = Math.min(Math.floor(scaled), ZONE_COUNT - 1);
54	  return { scene: SCENE_ORDER[index], local: clamp01(scaled - index) };
55	}
56	
57	/**
58	 * Splits a zone into `steps` equal milestones. The final milestone owns the
59	 * end of the zone, so scrolling a scene fully through always finishes it.
60	 */
61	export function stepAtProgress(steps: number, local: number): number {
62	  if (steps <= 1) return 0;
63	  const slice = Math.floor(clamp01(local) * steps);
64	  return Math.min(slice, steps - 1);
65	}
66	
67	/* ── autoplay timing ───────────────────────────────────────────────────────
68	   A uniform beat is what makes a demo read as a robot stepping through slides.
69	   Real use has a rhythm: the press itself is over in a moment, the screen it
70	   opens has to be readable, and the finished result wants a breath before the
71	   session starts again. Scenes declare a duration per step from this vocabulary. */
72	
73	/** A press: long enough to see the key light and the control sink, no longer. */
74	export const TAP_MS = 300;
75	/** A screen the eye has to actually read before the next move. */
76	export const BEAT_MS = 780;
77	/** A moment on something worth looking at — an amount landing, a QR appearing. */
78	export const DWELL_MS = 1150;
79	/**
80	 * The finished frame, held before the session replays. Without it the loop snaps
81	 * from a completed workflow straight back to an empty first screen, which reads
82	 * as a glitch rather than as the same person starting over.
83	 */
84	export const HOLD_MS = 2100;
85	
86	/** Fallback for a scene that declares no rhythm of its own. */
87	export function uniformBeats(steps: number, ms = BEAT_MS): number[] {
88	  if (steps <= 1) return [HOLD_MS];
89	  return Array.from({ length: steps }, (_, i) => (i === steps - 1 ? HOLD_MS : ms));
90	}
91	
92	/** One full play-through, in milliseconds. */
93	export function cycleLength(beats: readonly number[]): number {
94	  let total = 0;
95	  for (const b of beats) total += b > 0 && Number.isFinite(b) ? b : 0;
96	  return total > 0 ? total : HOLD_MS;
97	}
98	
99	/**
100	 * Step of an *autoplaying* scene, `elapsed` ms after it began.
101	 *
102	 * `beats[i]` is how long step `i` stays on screen. The scene plays 0 → last and
103	 * then repeats, so the phone performs the workflow rather than waiting to be
104	 * scrubbed through it. Kept pure and separate from the rAF loop that feeds it,
105	 * so the looping contract is unit tested rather than eyeballed in a browser —
106	 * exactly like the scroll mapping above it.
107	 */
108	export function stepAtElapsed(beats: readonly number[], elapsed: number): number {
109	  if (beats.length <= 1) return 0;
110	  const ms = Number.isFinite(elapsed) && elapsed > 0 ? elapsed : 0;
111	  let t = ms % cycleLength(beats);
112	  for (let i = 0; i < beats.length; i++) {
113	    const b = beats[i] > 0 && Number.isFinite(beats[i]) ? beats[i] : 0;
114	    if (t < b) return i;
115	    t -= b;
116	  }
117	  return beats.length - 1;
118	}
119	
120	export type StepsFor = (scene: LandingPhoneScene) => number;
121	
122	/** The single source of truth: progress in, complete state out. */
123	export function resolveState(progress: number, stepsFor: StepsFor): LandingPhoneState {
124	  const { scene, local } = sceneAtProgress(progress);
125	  return { scene, step: stepAtProgress(stepsFor(scene), local) };
126	}
127	
128	/** Reduced-motion and Save-Data viewers get the finished frame, not the build-up. */
129	export function finalState(scene: LandingPhoneScene, stepsFor: StepsFor): LandingPhoneState {
130	  return { scene, step: Math.max(0, stepsFor(scene) - 1) };
131	}
132	
133	export const sameState = (a: LandingPhoneState, b: LandingPhoneState) =>
134	  a.scene === b.scene && a.step === b.step;
135	
136	/**
137	 * Wraps `resolveState` so React only re-renders on an actual milestone change.
138	 * Scroll fires far more often than the demo changes; without this the phone
139	 * would set state on every frame.
140	 */
141	export function createSceneController(stepsFor: StepsFor, initial?: LandingPhoneState) {
142	  let current: LandingPhoneState = initial ?? { scene: SCENE_ORDER[0], step: 0 };
143	  return {
144	    get state(): LandingPhoneState {
145	      return current;
146	    },
147	    /** Returns the new state only when it changed, else null. */
148	    update(progress: number): LandingPhoneState | null {
149	      const next = resolveState(progress, stepsFor);
150	      if (sameState(next, current)) return null;
151	      current = next;
152	      return next;
153	    },
154	    /** Direct selection, used by the Industries tabs and replay control. */
155	    set(next: LandingPhoneState): LandingPhoneState | null {
156	      if (sameState(next, current)) return null;
157	      current = next;
158	      return next;
159	    },
160	  };
161	}

